pub fn read_original_root_task_generation(
    &self,
) -> Result<NeuronGenerationInitialReadbackV1, AgentdError> {
    require_original_session(&self.session, self.end)?;
    let observed = OriginalRootCircuitTaskCustodyV1::read_original_operation(&self.custody)?;
    OriginalHostInitialOperation::require_observed(&self.operation, &observed)?;
    require_original_session(&self.session, self.end)?;
    Ok(observed)
}

pub fn pending_original_root_task_operations(&self) -> Result<usize, AgentdError> {
    self.read_original_root_task_generation()?;
    let pending = self.runtime.bootstrap.handle().pending_count();
    require_original_session(&self.session, self.end)?;
    Ok(pending)
}

pub fn drain_completed_original_root_task(
    &self,
) -> Result<PublishedCircuitFeatureCompletionV1, AgentdError> {
    self.read_original_root_task_generation()?;
    let completion = OriginalRootCircuitTaskCustodyV1::drain_completed_task(&self.custody)?;
    self.read_original_root_task_generation()?;
    Ok(completion)
}

pub fn prepare_original_root_task<SW, CW>(
    self,
    inputs: OriginalRootCircuitTaskInputsV1<SW, CW>,
) -> Result<PreparedRootHostCircuitTaskV1<SW, CW>, RootHostInitialTaskInstallationErrorV1>
where
    SW: AnchorWitnessStore + Send + 'static,
    CW: AnchorWitnessStore + Send + 'static,
{
    let Self { session, operation, phase, end } = self;
    let install = (|| -> Result<_, OriginalInstallationFailure> {
        require_original_session(&session, end)?;
        let identity = session.registration.registered_identity.identity()
            .map_err(AgentdError::from)?;
        let InitialHostPhase::Ready(custody) = phase else {
            return Err(invalid("the original host generation is not Ready").into());
        };
        OriginalHostInitialOperation::require_observed(
            &operation,
            &OriginalRootInitialGenerationCustodyV1::read_original_operation(&custody)?,
        )?;
        let (runtime, custody) = OriginalRootInitialGenerationCustodyV1::into_original_root_task_channel(
            custody, &identity, inputs,
        ).map_err(OriginalInstallationFailure::Factory)?;
        OriginalHostInitialOperation::require_observed(
            &operation,
            &OriginalRootCircuitTaskCustodyV1::read_original_operation(&custody)?,
        )?;
        require_original_session(&session, end)?;
        Ok((runtime, custody))
    })();
    match install {
        Ok((runtime, custody)) => Ok(PreparedRootHostCircuitTaskV1 {
            session: Arc::new(session), operation: Arc::new(operation), runtime,
            custody: Arc::new(custody), material_source_taken: false, end,
        }),
        Err(failure) => Err(RootHostInitialTaskInstallationErrorV1 {
            session, operation, end, failure,
        }),
    }
}

pub fn handoff_and_serve_original_root_circuit_task(
    &mut self, production_handoff: UnixDatagram, task_handoff: UnixDatagram,
    original_root_pidfd: OwnedFd, consumer_state_root: &Path,
    task_path: PathBuf, loan_path: PathBuf, session_nonce: [u8; 16],
) -> Result<u64, AgentdError> {
    let startup_end = (Instant::now() + Duration::from_secs(30)).min(self.end);
    self.read_original_root_task_generation()?;
    let identity = self.session.registration.registered_identity.identity()?;
    if rustix::process::getuid().as_raw() != 0 || rustix::process::geteuid().as_raw() != 0
        || self.session.config.peer_uid == 0
        || self.session.registration.peer_pid == std::process::id()
        || session_nonce == [0; 16]
    { return Err(AgentdError::Invalid("original Root task registration differs".into())); }
    let (binding, registry, source, capacity) = self.runtime.original_root_handoff_data()?;
    let lane = self.runtime.take_original_root_lane()?;
    let bound = listeners::TaskListeners::bind(&task_path, &loan_path, self.session.config.peer_gid)?;
    let original_host = self.session.bind_original_task_host_lanes()?;
    let original_bootstrap = self.session.seal_bootstrap(consumer_state_root)?;
    let descriptor = crate::root_original_task_descriptor::seal(
        std::process::id(), self.session.registration.peer_pid,
        self.session.config.peer_uid, self.session.config.peer_gid,
        &task_path, &loan_path, session_nonce, self.end, capacity, binding, &registry, &source,
    )?;
    self.read_original_root_task_generation()?;
    let remaining = startup_end.checked_duration_since(Instant::now())
        .filter(|value| !value.is_zero()).ok_or_else(|| AgentdError::Invalid("Root task startup expired".into()))?;
    crate::send_root_production_handoff(production_handoff, &original_bootstrap,
        &original_root_pidfd, remaining)?;
    let remaining = startup_end.checked_duration_since(Instant::now())
        .filter(|value| !value.is_zero()).ok_or_else(|| AgentdError::Invalid("Root task startup expired".into()))?;
    crate::root_production_handoff::send_original_task_handoff(
        task_handoff, &descriptor, &original_root_pidfd, remaining,
    )?;
    let root: &PreparedRootHostCircuitTaskV1<SW, CW> = self;
    std::thread::scope(|scope| {
        // This is a real, already-Root host process. The ordinary daemon
        // performs its own process credential drop before either connect.
        let host = scope.spawn(move || original_host.serve());
        let task_result = (|| {
            let (task, loan) = bound.accept(&root.session.owner_pidfd, startup_end)?;
            root.read_original_root_task_generation()?;
            require_before(startup_end)?;
            let lifetime = root.end.checked_duration_since(Instant::now())
                .filter(|value| !value.is_zero() && *value <= Duration::from_secs(300))
                .ok_or_else(|| AgentdError::Invalid("original Root task scope expired".into()))?;
            let policy = HostAuthorityPeerPolicy {
                peer: HostIssuerPeer { uid: root.session.config.peer_uid, pid: root.session.registration.peer_pid },
                timeout: Duration::from_millis(root.session.config.timeout_ms.min(500)), lifetime,
                request_bound: 65_536, response_bound: 65_536,
            };
            let task_fd = task.as_raw_fd();
            let task = HostAuthorityPeerChannel::from_stream(task, policy, root.session.owner_pidfd.try_clone()?)
                .map_err(protocol)?;
            let loan = HostAuthorityPeerChannel::from_stream(loan, policy, root.session.owner_pidfd.try_clone()?)
                .map_err(protocol)?;
            listeners::wait_first_frame(task_fd, &root.session.owner_pidfd, startup_end)?;
            root.read_original_root_task_generation()?;
            let end = root.end;
            crate::circuit_task::remote::serve(root, &identity, lane,
                OriginalRootTaskStreams::new(task, loan, session_nonce, end)).map_err(protocol)
        })();
        let host_result = host.join()
            .map_err(|_| AgentdError::Protocol("original Root service panicked".into()))?
            .map_err(AgentdError::from);
        match (task_result, host_result) {
            (Ok(count), Ok(())) => Ok(count),
            (Err(task), Ok(())) => Err(task),
            (Ok(_), Err(host)) => Err(host),
            (Err(task), Err(host)) => Err(AgentdError::Protocol(format!(
                "original task result Unknown: {task}; original host termination: {host}"))),
        }
    })
}

pub fn serve_original_root_circuit_task(&mut self, task: UnixStream, loan: UnixStream,
    session_nonce: [u8; 16]) -> Result<u64, AgentdError>
{
    self.read_original_root_task_generation()?;
    let identity = self.session.registration.registered_identity.identity()?;
    if self.session.config.peer_uid == 0 || self.session.registration.peer_pid == std::process::id()
        || session_nonce == [0; 16]
    { return Err(AgentdError::Invalid("original Root task peer or session differs".into())); }
    let lifetime = self.end.checked_duration_since(Instant::now())
        .filter(|value| !value.is_zero() && *value <= Duration::from_secs(300))
        .ok_or_else(|| AgentdError::Invalid("original Root task scope expired".into()))?;
    let policy = HostAuthorityPeerPolicy {
        peer: HostIssuerPeer { uid: self.session.config.peer_uid, pid: self.session.registration.peer_pid },
        timeout: Duration::from_millis(self.session.config.timeout_ms.min(500)), lifetime,
        request_bound: 65_536, response_bound: 65_536,
    };
    let task = HostAuthorityPeerChannel::from_stream(task, policy, self.session.owner_pidfd.try_clone()?)
        .map_err(|error| AgentdError::Protocol(error.to_string()))?;
    let loan = HostAuthorityPeerChannel::from_stream(loan, policy, self.session.owner_pidfd.try_clone()?)
        .map_err(|error| AgentdError::Protocol(error.to_string()))?;
    let lane = self.runtime.take_original_root_lane()?;
    crate::circuit_task::remote::serve(self, &identity, lane,
        OriginalRootTaskStreams::new(task, loan, session_nonce, self.end))
        .map_err(|error| AgentdError::Protocol(format!("original Root task service: {error}")))
}

pub(crate) fn require_original_root_task_source(&self,
    source: &Arc<CircuitTaskSourceReadbackV1<SW>>) -> Result<(), AgentdError>
{
    self.read_original_root_task_generation()?;
    OriginalRootCircuitTaskCustodyV1::require_original_source(&self.custody, source)
}

pub fn prepare_original_material_source_host(&mut self)
    -> Result<PreparedRootMaterialSourceHostV1<SW, CW>, AgentdError>
{
    self.read_original_root_task_generation()?;
    if self.material_source_taken {
        return Err(AgentdError::Invalid("original Material Source service already exported".into()));
    }
    self.material_source_taken = true;
    let host = PreparedRootMaterialSourceHostV1 {
        session: Arc::clone(&self.session), operation: Arc::clone(&self.operation),
        custody: Arc::clone(&self.custody), end: self.end,
    };
    host.require_current()?;
    Ok(host)
}

pub fn serve(self, registration: OriginalRootMaterialSourceRegistrationV1)
    -> Result<u64, AgentdError>
{
    self.require_current()?;
    let registration::OriginalRootMaterialSourceRegistrationV1 {
        material, consumer, consumer_uid, original_consumer_pidfd, stream, nonce,
    } = registration;
    if consumer.pid == self.session.registration.peer_pid {
        return Err(protocol("the registered daemon is not the original Material process"));
    }
    let binding = wire::context(&material).map_err(protocol)?;
    let timeout = Duration::from_millis(self.session.config.timeout_ms.min(500));
    let lifetime = self.end.checked_duration_since(Instant::now())
        .filter(|value| !value.is_zero() && *value <= Duration::from_secs(300))
        .ok_or_else(|| protocol("original Material Source scope expired"))?;
    let mut channel = original_owner_command_channel_v1(stream, consumer, consumer_uid,
        original_consumer_pidfd, timeout, lifetime).map_err(protocol)?;
    self.require_current()?;
    wire::before(self.end).map_err(protocol)?;
    for id in 1..=wire::LIMIT {
        let request = wire::request(binding, nonce, id).map_err(protocol)?;
        let mut failure = None;
        let mut deadline = None;
        let exchanged = channel.exchange(|bytes| {
            let result = (|| -> Result<Vec<u8>, AgentdError> {
                let until = (Instant::now() + timeout).min(self.end);
                deadline = Some(until);
                wire::before(until).map_err(protocol)?;
                if bytes != request || wire::context(&material).map_err(protocol)? != binding {
                    return Err(protocol("original Material Source request differs"));
                }
                self.require_current()?;
                let payload = OriginalRootCircuitTaskCustodyV1::read_original_material_source(
                    &self.custody, &material.initial.request,
                )?;
                self.require_current()?;
                if wire::context(&material).map_err(protocol)? != binding {
                    return Err(protocol("original Material Source context changed"));
                }
                let response = wire::response(&request, &payload).map_err(protocol)?;
                wire::before(until).map_err(protocol)?;
                Ok(response)
            })();
            result.map_err(|error| { failure = Some(error); HostIssuerTransportError::Unavailable })
        });
        match exchanged {
            Ok(false) => { self.require_current()?; return Ok(id - 1); }
            Ok(true) => {
                channel.check_peer_lifetime().map_err(protocol)?;
                self.require_current()?;
                if wire::context(&material).map_err(protocol)? != binding {
                    return Err(protocol("original Material Source context changed after response"));
                }
                let until = deadline.ok_or_else(|| protocol("original Source deadline missing"))?;
                wire::before(until).map_err(protocol)?;
            }
            Err(error) => return Err(failure.unwrap_or_else(|| protocol(error))),
        }
    }
    Err(protocol("original Material Source request bound exhausted"))
}

pub(crate) fn bind_original_task_host_lanes(&self) -> io::Result<OriginalTaskHostLanes<'_>> {
    if rustix::process::getuid().as_raw() != 0 || rustix::process::geteuid().as_raw() != 0 {
        return Err(io::Error::other("same actual Root service required"));
    }
    // Those optional services have their own consuming original serving
    // APIs. This bounded composition never silently drops either owner.
    if self.root_admin.is_some() || self.learning.is_some() {
        return Err(io::Error::other("original task host cannot discard optional retained lanes"));
    }
    let bound = super::super::listeners::bind_runtime_lanes(&self.config, || Ok(()))?;
    Ok(OriginalTaskHostLanes { service: &self.service, config: &self.config,
        registration: &self.registration, owner: &self.owner_pidfd, bound })
}

pub(crate) fn serve(self) -> io::Result<()> {
    super::super::listeners::serve_bound_lanes(self.service, self.config,
        self.registration, self.owner, self.bound)
}

pub(super) fn bind(task: &PathBuf, loan: &PathBuf, gid: u32) -> Result<Self, AgentdError> {
    crate::authority_host_runtime::validate_lane_paths(&[task, loan], gid)?;
    let mut guard = SocketGuard(Vec::new());
    let task = bind_one(task, gid, &mut guard)?;
    let loan = bind_one(loan, gid, &mut guard)?;
    Ok(Self { task, loan, guard })
}

pub(super) fn accept(&self, owner: &OwnedFd, end: Instant) -> Result<(UnixStream, UnixStream), AgentdError> {
    // The same fixed end covers both accepts; no per-lane startup renewal.
    let task = accept_one(&self.task, owner, end)?;
    let loan = accept_one(&self.loan, owner, end)?;
    for (path, device, inode) in &self.guard.0 {
        let entry = fs::symlink_metadata(path)?;
        if entry.dev() != *device || entry.ino() != *inode {
            return Err(AgentdError::Invalid("original task listener changed".into()));
        }
    }
    require_before(end)?;
    Ok((task, loan))
}

pub(super) fn wait_first_frame(fd: RawFd, owner: &OwnedFd, end: Instant) -> Result<(), AgentdError> {
    loop {
        require_before(end)?;
        crate::root_observation_stream::check_lifetime(owner).map_err(protocol)?;
        let left = end.saturating_duration_since(Instant::now());
        let millis = i32::try_from(left.as_millis().saturating_add(1))
            .map_err(|_| AgentdError::Invalid("original task startup bound differs".into()))?;
        let mut entry = libc::pollfd { fd, events: libc::POLLIN, revents: 0 };
        // SAFETY: poll borrows one live descriptor held by the original HAP
        // channel and writes only this initialized scalar pollfd.
        let result = unsafe { libc::poll(&mut entry, 1, millis) };
        if result < 0 {
            let error = std::io::Error::last_os_error();
            if error.kind() == std::io::ErrorKind::Interrupted { continue; }
            return Err(error.into());
        }
        require_before(end)?;
        crate::root_observation_stream::check_lifetime(owner).map_err(protocol)?;
        if result == 0 || entry.revents & (libc::POLLERR | libc::POLLHUP | libc::POLLNVAL) != 0 {
            return Err(AgentdError::Protocol("original task peer ended before its first request".into()));
        }
        if entry.revents & libc::POLLIN != 0 { return Ok(()); }
    }
}

pub(crate) fn require_source(
    identity: &AgentdIdentity,
    source: &CircuitTaskSourcePublicationV1,
    request: &LearningIterationRequestV1,
) -> Result<(), CellQ24DatasetErrorV1> {
    let input = source.input();
    let original = source.original_record();
    let selected = request
        .selected_bundle
        .digest()
        .map_err(LearningIterationError::from)?;
    if identity.agent_id.as_str() != request.agent_id.as_str()
        || input.scope.principal_digest.to_string() != request.principal_id.as_str()
        || input.scope.agent_id != request.agent_id
        || input.scope.cell_id != request.cell_id
        || input.scope.run_id != request.source_run_id
        || original.snapshot.run_id != request.source_run_id
        || input.objective_digest != request.envelope.objective_digest
        || original.snapshot.objective_digest != request.envelope.objective_digest
        || source.history_digest().as_str() != request.completed_task_receipt.to_string()
        || source.bundle_digest() != selected
    {
        return Err(CellQ24DatasetErrorV1::Binding(
            "original task identity, receipt and bundle",
        ));
    }
    Ok(())
}

pub fn into_original_root_source_command_owner(
    self, stream: UnixStream, root: AgentdRootAuthorityPeer, root_pidfd: OwnedFd,
    nonce: [u8; 16], identity: AgentdIdentity, ledger: Arc<Mutex<LedgerWriter>>,
    baseline: Arc<LoadedCellQ24ModelV1>, timeout: Duration, lifetime: Duration,
) -> Result<OriginalCellQ24MaterialCommandOwnerV1<EW, DW, FileAnchorWitnessStore>,
    OriginalCellQ24MaterialCommandErrorV1>
{
    let source = CircuitTaskSourceReadbackV1::from_original_material_root_stream(
        stream, root, root_pidfd, self.config.clone(), identity.clone(), nonce, timeout, lifetime,
    ).map_err(|error| OriginalCellQ24MaterialCommandErrorV1::Dataset(
        CellQ24DatasetErrorV1::Source(error)))?;
    OriginalCellQ24MaterialReceiptOwnersV1::into_command_owner(
        self, source, identity, ledger, baseline,
    )
}

pub(crate) fn original_source_loan_binding(&self, at: u64) -> Result<Digest32, Error> {
    wire::context_binding(self, at)
}

pub(crate) fn encode(registry: &CircuitCellRegistryV1) -> Result<Vec<u8>, Error> {
    let mut out = Writer::new(b"HCRTRGY1");
    out.json(&registry.definition)?;
    out.count(registry.bindings.len(), 16)?;
    for binding in &registry.bindings {
        out.text(&binding.program_id)?;
        out.text(&binding.node_id)?;
        root_bootstrap_cell::encode(&mut out, &binding.cell)?;
        out.count(binding.routes.len(), 256)?;
        for route in &binding.routes {
            out.id(&route.candidate_id)?;
            out.json(&route.outcome)?;
            out.count(route.selected_edges.len(), 256)?;
            for edge in &route.selected_edges { out.text(edge)?; }
        }
    }
    Ok(out.finish())
}

pub(crate) fn decode(bytes: &[u8]) -> Result<CircuitCellRegistryV1, Error> {
    let mut input = Reader::new(bytes, b"HCRTRGY1")?;
    let definition = input.json()?;
    let mut bindings = Vec::new();
    for _ in 0..input.count(16)? {
        let program_id = input.text()?;
        let node_id = input.text()?;
        let cell = root_bootstrap_cell::decode(&mut input)?;
        let mut routes = Vec::new();
        for _ in 0..input.count(256)? {
            let candidate_id = input.id()?;
            let outcome = input.json()?;
            let mut selected_edges = Vec::new();
            for _ in 0..input.count(256)? { selected_edges.push(input.text()?); }
            routes.push(CircuitCellRouteV1 { candidate_id, outcome, selected_edges });
        }
        bindings.push(CircuitCellBindingV1 { program_id, node_id, cell, routes });
    }
    input.end()?;
    let registry = CircuitCellRegistryV1::new(definition, bindings)?;
    if encode(&registry)? != bytes { return Err(Error::InvalidBinding); }
    Ok(registry)
}

pub(crate) fn execute_original_remote(
    &mut self,
    admission: OriginalRemoteAdmission,
    input: CellStepInputV1,
    mut clock: impl FnMut() -> CircuitCellTimeV1,
) -> Result<CircuitCellExecutionV1, CircuitCellErrorV1> {
    admission.require_current().map_err(|_| CircuitCellErrorV1::ReconciliationRequired)?;
    let original_clock = &mut clock;
    let loan_failed = Cell::new(false);
    let mut clock = || {
        if !loan_failed.get() {
            if let Ok(now_ms) = admission.require_current() {
                let sampled = original_clock();
                return CircuitCellTimeV1 {
                    circuit_millis: sampled.circuit_millis.max(now_ms),
                    cell_micros: sampled.cell_micros,
                };
            }
            loan_failed.set(true);
        }
        CircuitCellTimeV1 { circuit_millis: u64::MAX, cell_micros: u64::MAX }
    };
    let dispatch = admission.dispatch();
    let binding = self.registry.bind_input(dispatch, &input)?;
    let request_digest = canonical_cell_step_request_digest_v1(&binding.cell, &input)?;
    if admission.owner_agent_id() != input.scope.agent_id.as_str()
        || admission.definition_digest() != self.registry.definition_digest()
        || admission
            .execution_request_digest()
            .is_none_or(|digest| digest.as_str() != request_digest.to_string())
    {
        return Err(CircuitCellErrorV1::ScopeMismatch);
    }
    let time = clock();
    if time.circuit_millis < admission.observed_at_ms() {
        return Err(CircuitCellErrorV1::ReconciliationRequired);
    }
    let admission_deadline = admission
        .lease_expires_at_ms()
        .min(admission.run_deadline_ms());
    let read_only =
        admission.reconciliation_only() || time.circuit_millis >= admission_deadline;
    let committed =
        match self
            .state_owner
            .lookup(&input.scope, &input.operation_id, request_digest)
        {
            Ok(receipt) => receipt,
            Err(CellExecutionError::InferencePending) => None,
            Err(error) => return Err(error.into()),
        };
    let mut last_time = time;
    let decision = if let Some(receipt) = committed {
        receipt
    } else {
        let pending = self.state_owner.pending_inference(&input.scope)?;
        let inferred = if pending.is_some() {
            recover_cell_inference(
                &binding.cell,
                &self.state_owner,
                &self.encoder,
                input.clone(),
                &mut self.inference_control,
                time.cell_micros,
            )?
        } else {
            if read_only {
                return Err(CircuitCellErrorV1::ReconciliationRequired);
            }
            match enter_cell_step(
                &binding.cell,
                &self.state_owner,
                &self.encoder,
                input.clone(),
                time.cell_micros,
            )? {
                CellStepEntryV1::Ready(prepared) => {
                    let sampled = Cell::new(time);
                    // The inference entry samples immediately after durable
                    // admission. Use that same live sample for the Circuit
                    // guard so its queue measurement ends at this boundary.
                    let mut dispatch_clock = || sampled.get();
                    let mut guarded = GuardedCellDispatchV1::new(
                        &mut self.inference_control,
                        &mut dispatch_clock,
                        time,
                        admission_deadline,
                        input.deadline_micros,
                    );
                    let mut invalid_clock = false;
                    let inferred = infer_cell_with_clock(
                        *prepared,
                        &mut self.state_owner,
                        &mut guarded,
                        || {
                            let before = sampled.get();
                            let now = clock();
                            if now.circuit_millis < before.circuit_millis
                                || now.cell_micros < before.cell_micros
                                || now.circuit_millis >= admission_deadline
                            {
                                invalid_clock = true;
                                return u64::MAX;
                            }
                            sampled.set(now);
                            now.cell_micros
                        },
                    );
                    if invalid_clock {
                        return Err(CircuitCellErrorV1::ReconciliationRequired);
                    }
                    let inferred = inferred?;
                    last_time = guarded
                        .observed_at()
                        .ok_or(CircuitCellErrorV1::ReconciliationRequired)?;
                    inferred
                }
                CellStepEntryV1::Replayed(receipt) => {
                    if loan_failed.get() {
                        return Err(CircuitCellErrorV1::ReconciliationRequired);
                    }
                    admission.require_current().map_err(|_| CircuitCellErrorV1::ReconciliationRequired)?;
                    return finish(binding, dispatch, &input, *receipt);
                }
            }
        };
        let decided_at = clock();
        if decided_at.circuit_millis < last_time.circuit_millis
            || decided_at.cell_micros < last_time.cell_micros
        {
            return Err(CircuitCellErrorV1::ReconciliationRequired);
        }
        let proposal = decide_cell(inferred, decided_at.cell_micros)?;
        let committed_at = clock();
        if committed_at.circuit_millis < decided_at.circuit_millis
            || committed_at.cell_micros < decided_at.cell_micros
        {
            return Err(CircuitCellErrorV1::ReconciliationRequired);
        }
        commit_cell_step(&mut self.state_owner, proposal, committed_at.cell_micros)?
    };
    if loan_failed.get() {
        return Err(CircuitCellErrorV1::ReconciliationRequired);
    }
    admission.require_current().map_err(|_| CircuitCellErrorV1::ReconciliationRequired)?;
    finish(binding, dispatch, &input, decision)
}

pub(crate) fn read_original_material_publication<CW: AnchorWitnessStore, SW: AnchorWitnessStore>(
    &self, cell: &PublishedCircuitCellOwnerV1<CW>, source: &CircuitTaskSourceReadbackV1<SW>,
    identity: &AgentdIdentity, run: &StableId,
) -> Result<CircuitTaskSourcePublicationV1, AgentdError> {
    if !Arc::ptr_eq(&self.0, &cell.task.0) || run != &self.source().scope.run_id {
        return Err(invalid("Material Source belongs to a different original task"));
    }
    self.require_current()?;
    let observed = source.read_run_publication(identity, run).map_err(invalid)?;
    let decision = cell.committed(&observed)?;
    if source.read_run_publication(identity, run).map_err(invalid)? != observed
        || cell.committed(&observed)? != decision
    { return Err(invalid("original Material Source or Cell changed")); }
    self.require_current()?;
    Ok(observed)
}

pub(crate) fn original_root_handoff_data(&self)
    -> Result<(codex_hepta_types::Digest32, Vec<u8>, Vec<u8>, usize), AgentdError>
{
    let (registry, capacity) = self.bootstrap.original_root_handoff_registry()
        .map_err(|error| AgentdError::Protocol(format!("original Root registry: {error}")))?;
    let (binding, source) = self.invocation.original_root_handoff_source()
        .map_err(|error| AgentdError::Protocol(format!("original Root Source: {error}")))?;
    Ok((binding, registry, source, capacity))
}

pub(crate) fn take_original_root_lane(&mut self)
    -> Result<crate::circuit_task::OriginalRootTaskLane<SW>, AgentdError>
{
    let pump = self.bootstrap.take_original_root_lane()
        .map_err(|error| AgentdError::Protocol(format!("original Root Cell lane: {error}")))?;
    Ok(crate::circuit_task::OriginalRootTaskLane::from_original_factory(
        pump, Arc::clone(&self.invocation), Arc::clone(&self.source),
    ))
}

pub(super) async fn execute(
    &mut self,
    request: &CircuitTaskRequestV1,
    mode: CircuitTaskModeV1,
    mut clock: impl FnMut() -> Result<CircuitCellTimeV1, Error> + Send,
) -> Result<CircuitTaskReceiptV1, Error> {
    let circuit_deadline = request
        .start
        .created_at_ms
        .checked_add(self.cells.registry().definition().limits.max_elapsed_ms)
        .ok_or(Error::InvalidBinding)?;
    clock()?;
    let existing = self
        .store
        .read_bounded_circuit_task(
            self.cells.registry().definition(),
            &request.start,
            &self.fence,
        )
        .await?;
    let before_create = clock()?;
    let mut run = match &existing {
        Some(trace) => trace.run().clone(),
        None => {
            if matches!(mode, CircuitTaskModeV1::Readback) {
                return Err(Error::ReconciliationRequired);
            }
            require_before_deadline(request, before_create)?;
            self.store
                .create_bounded_circuit_run(
                    self.cells.registry().definition(),
                    &request.start,
                    &self.fence,
                )
                .await
                .map_err(mutation_error)?
                .run
        }
    };
    let mut completed = match (existing, run.outcome(), mode) {
        (Some(trace), None, CircuitTaskModeV1::Drive) => self.materialize(request, &trace)?,
        _ => BTreeMap::new(),
    };
    loop {
        let time = clock()?;
        if run.outcome().is_some() || matches!(mode, CircuitTaskModeV1::Readback) {
            let trace = self
                .store
                .read_bounded_circuit_task(
                    self.cells.registry().definition(),
                    &request.start,
                    &self.fence,
                )
                .await?
                .ok_or(Error::ReconciliationRequired)?;
            let executions = self.materialize(request, &trace)?;
            clock()?;
            return Ok(CircuitTaskReceiptV1 { trace, executions });
        }
        require_before_deadline(request, time)?;
        if let Some(pending) = run.activations().values().find(|activation| {
            matches!(
                activation.status,
                CircuitActivationStatusV2::InFlight | CircuitActivationStatusV2::Indeterminate
            )
        }) {
            let activation_id = pending.activation_id;
            let status = pending.status;
            let observed = self
                .store
                .recover_circuit_computation(
                    &request.start.run_id,
                    activation_id,
                    &self.fence,
                    time.circuit_millis,
                )
                .await?;
            let input_mode = if observed.execution_request_digest().is_some() {
                CircuitTaskInputModeV1::Readback
            } else {
                CircuitTaskInputModeV1::Prepare
            };
            let input =
                self.inputs
                    .resolve(request, observed.dispatch(), &completed, input_mode)?;
            self.validate_input(request, &input)?;
            let binding = self
                .cells
                .registry()
                .bind_input(observed.dispatch(), &input)?;
            let digest = canonical_cell_step_request_digest_v1(&binding.cell, &input)
                .map_err(CircuitCellErrorV1::from)?;
            let execution_request_digest =
                Sha256Digest::parse(digest.to_string()).map_err(|_| Error::InvalidBinding)?;
            let before_claim = clock()?;
            require_before_deadline(request, before_claim)?;
            let admission = if observed.execution_request_digest().is_none() {
                self.store
                    .claim_circuit_computation(&CircuitComputationClaimV2 {
                        run_id: request.start.run_id.clone(),
                        activation_id,
                        command_id: format!("task-cell-claim:{activation_id}"),
                        fence: self.fence.clone(),
                        expected_revision: observed.observed_revision(),
                        now_ms: before_claim.circuit_millis,
                        execution_request_digest,
                    })
                    .await
                    .map_err(mutation_error)?
            } else {
                observed
            };
            let expected_revision = admission.observed_revision();
            // Synchronous inference stays on the one owned blocking lane.
            // Once authority or time fails, every remaining clock sample
            // is fenced; returning authority later cannot revive this call.
            let mut clock_error = None;
            let execution = self.cells.execute(admission, input, || {
                if clock_error.is_none() {
                    match clock().and_then(|time| {
                        require_before_deadline(request, time)?;
                        Ok(time)
                    }) {
                        Ok(time) => return time,
                        Err(error) => clock_error = Some(error),
                    }
                }
                CircuitCellTimeV1 {
                    circuit_millis: u64::MAX,
                    cell_micros: u64::MAX,
                }
            });
            if let Some(error) = clock_error {
                return Err(error);
            }
            let execution = execution?;
            let after = clock()?;
            require_before_deadline(request, after)?;
            let event = if status == CircuitActivationStatusV2::Indeterminate {
                CircuitEventV2::Reconcile {
                    completion: execution.completion.clone(),
                }
            } else {
                CircuitEventV2::Complete {
                    completion: execution.completion.clone(),
                }
            };
            run = self
                .store
                .apply_bounded_circuit_command(&CircuitCommandV2 {
                    run_id: request.start.run_id.clone(),
                    command_id: format!("task-cell-complete:{activation_id}"),
                    fence: self.fence.clone(),
                    expected_revision,
                    now_ms: after.circuit_millis,
                    event,
                })
                .await
                .map_err(mutation_error)?
                .run;
            completed.insert(activation_id, execution);
            continue;
        }
        let wake_at = run
            .activations()
            .values()
            .filter_map(|activation| match activation.status {
                CircuitActivationStatusV2::Ready => Some(activation.ready_at_ms),
                CircuitActivationStatusV2::Joining => activation.join_deadline_ms(),
                CircuitActivationStatusV2::InFlight
                | CircuitActivationStatusV2::Indeterminate
                | CircuitActivationStatusV2::ChildRunning
                | CircuitActivationStatusV2::Completed
                | CircuitActivationStatusV2::Cancelled => None,
            })
            .min()
            .unwrap_or(circuit_deadline)
            .min(circuit_deadline);
        if wake_at > time.circuit_millis {
            // Waiting does not append empty Advance events or spend event
            // budget. Revalidate generation, trust and cancellation often.
            let delay = wake_at
                .min(request.deadline_ms)
                .saturating_sub(time.circuit_millis)
                .min(250);
            tokio::time::sleep(Duration::from_millis(delay)).await;
            run = self
                .store
                .bounded_circuit_run(&request.start.run_id)
                .await?
                .ok_or(Error::ReconciliationRequired)?;
            continue;
        }
        let before_advance = clock()?;
        require_before_deadline(request, before_advance)?;
        run = self
            .store
            .apply_bounded_circuit_command(&CircuitCommandV2 {
                run_id: request.start.run_id.clone(),
                command_id: format!("task-advance:{}", run.revision()),
                fence: self.fence.clone(),
                expected_revision: run.revision(),
                now_ms: before_advance.circuit_millis,
                event: CircuitEventV2::Advance { quantum: 1 },
            })
            .await
            .map_err(mutation_error)?
            .run;
    }
}

pub(super) fn from_original(original: &CircuitComputationAdmissionV2) -> Self {
    Self { dispatch: original.dispatch().clone(), owner: original.owner_agent_id().to_string(),
        definition: original.definition_digest().clone(), request: original.execution_request_digest().cloned(),
        revision: original.observed_revision(), observed: original.observed_at_ms(),
        lease_end: original.lease_expires_at_ms(), run_end: original.run_deadline_ms(),
        reconciliation: original.reconciliation_only() }
}

pub(super) fn encode(&self) -> Result<Vec<u8>, Error> {
    let mut bytes = b"HCRTADM1".to_vec();
    blob(&mut bytes, &data::encode_dispatch(&self.dispatch)?)?;
    blob(&mut bytes, self.owner.as_bytes())?;
    blob(&mut bytes, self.definition.as_str().as_bytes())?;
    blob(&mut bytes, self.request.as_ref().map_or(b"".as_slice(), |d| d.as_str().as_bytes()))?;
    for number in [self.revision, self.observed, self.lease_end, self.run_end] {
        bytes.extend_from_slice(&number.to_be_bytes());
    }
    bytes.push(u8::from(self.reconciliation));
    super::wire::bounded(&bytes)?;
    Ok(bytes)
}

pub(super) fn new(lane: Lane, binding: Digest32) -> Self {
    Self { lane: Arc::new(Mutex::new(lane)), binding }
}

pub(super) fn check_record(&self, id: u64, record: &[u8]) -> Result<u64, Error> {
    check_record(&self.lane, id, record)
}

pub(super) fn open_admission(
    &self, id: u64, record_id: u64, record: &[u8],
) -> Result<OriginalRemoteAdmission, Error> {
    let bytes = self.lane.try_lock().map_err(|_| Error::Unavailable)?.call(Frame {
        operation: Operation::OpenAdmission, loan: id, body: Vec::new(),
    })?;
    let mut r = Reader::new(&bytes, b"HCRTCHK1")?;
    if r.u64()? != record_id { return Err(Error::InvalidBinding); }
    let now = r.u64()?;
    if r.blob()? != record { return Err(Error::InvalidBinding); }
    let encoded = r.blob()?.to_vec();
    r.end()?;
    let data = AdmissionData::decode(&encoded)?;
    if now < data.observed { return Err(Error::ReconciliationRequired); }
    Ok(OriginalRemoteAdmission { lane: Arc::clone(&self.lane), id, record_id,
        record: record.to_vec(), encoded, data })
}

pub(super) fn completion(
    &self, id: u64, record_id: u64, record: &[u8], saved_input: &[u8],
) -> Result<OriginalRemoteCompletion, Error> {
    let bytes = self.lane.try_lock().map_err(|_| Error::Unavailable)?.call(Frame {
        operation: Operation::ReadCompletion, loan: id, body: Vec::new(),
    })?;
    let mut r = Reader::new(&bytes, b"HCRTCHK1")?;
    if r.u64()? != record_id { return Err(Error::InvalidBinding); }
    r.u64()?;
    if r.blob()? != record || r.blob()? != saved_input { return Err(Error::InvalidBinding); }
    let payload = r.blob()?.to_vec();
    r.end()?;
    self.check_record(record_id, record)?;
    Ok(OriginalRemoteCompletion { lane: Arc::clone(&self.lane), binding: self.binding,
        record_id, record: record.to_vec(), saved_input: saved_input.to_vec(), payload })
}

pub(super) fn terminal(&self, id: u64, record_id: u64) -> Result<(), Error> {
    let reply = self.lane.try_lock().map_err(|_| Error::Unavailable)?.call(Frame {
        operation: Operation::Terminal, loan: id, body: record_id.to_be_bytes().to_vec(),
    })?;
    if reply != b"HCRTEND1" { return Err(Error::InvalidBinding); }
    Ok(())
}

pub(crate) fn require_current(&self) -> Result<u64, Error> {
    let bytes = self.lane.try_lock().map_err(|_| Error::Unavailable)?.call(Frame {
        operation: Operation::CheckAdmission, loan: self.id, body: Vec::new(),
    })?;
    let mut r = Reader::new(&bytes, b"HCRTCHK1")?;
    if r.u64()? != self.record_id { return Err(Error::InvalidBinding); }
    let now = r.u64()?;
    if r.blob()? != self.record || r.blob()? != self.encoded { return Err(Error::InvalidBinding); }
    r.end()?;
    Ok(now)
}

pub(crate) fn into_original_payload(
    self, binding: Digest32, record: &[u8], saved_input: &[u8],
) -> Result<Vec<u8>, Error> {
    if self.binding != binding || self.record != record || self.saved_input != saved_input {
        return Err(Error::InvalidBinding);
    }
    check_record(&self.lane, self.record_id, &self.record)?;
    Ok(self.payload)
}

pub(crate) fn new_until(identity: &AgentdIdentity, inputs: OriginalRootCircuitTaskDaemonInputsV1,
    pending: Arc<AtomicUsize>, end: Instant) -> Result<(Arc<Self>, usize), Error>
{
    if Instant::now() >= end || end.saturating_duration_since(Instant::now()) > Duration::from_secs(300) {
        return Err(Error::DeadlineExceeded);
    }
    if rustix::process::getuid().as_raw() == 0 || rustix::process::geteuid().as_raw() == 0
        || inputs.original_root.uid != 0 || inputs.original_root.pid == std::process::id()
        || inputs.lifetime.is_zero() || inputs.lifetime > Duration::from_secs(300)
        || !(1..=64).contains(&inputs.queue_capacity)
        || inputs.fence.owner_agent_id != identity.agent_id
        || identity.spawn_generation.checked_add(1) != Some(inputs.fence.generation)
    { return Err(Error::InvalidBinding); }
    let binding = remote_source::original_binding(identity, &inputs.fence, &inputs.registry, &inputs.source)?;
    let budget = Budget::new(end)?;
    let policy = HostAuthorityPeerPolicy { peer: inputs.original_root, timeout: TIMEOUT,
        lifetime: inputs.lifetime, request_bound: FRAME_LIMIT, response_bound: FRAME_LIMIT };
    let stop_reverse = inputs.loan_stream.try_clone().map_err(|_| Error::Unavailable)?;
    let task = HostAuthorityPeerChannel::from_stream(inputs.task_stream, policy,
        inputs.original_root_task_pidfd).map_err(|_| Error::Unavailable)?;
    let reverse = HostAuthorityPeerChannel::from_stream(inputs.loan_stream, policy,
        inputs.original_root_loan_pidfd).map_err(|_| Error::Unavailable)?;
    let client = Self { identity: identity.clone(), fence: inputs.fence,
        registry: inputs.registry, source: inputs.source,
        task: Mutex::new(Lane::new(task, binding, inputs.session_nonce, LanePurpose::Task, Arc::clone(&budget))?),
        reverse: Mutex::new(Some(Lane::new(reverse, binding, inputs.session_nonce, LanePurpose::Loan, budget)?)),
        loans: DaemonLoans::new(pending), resolved: Mutex::new(None), stop_reverse };
    if Instant::now() >= end { return Err(Error::DeadlineExceeded); }
    Ok((Arc::new(client), inputs.queue_capacity))
}

pub(crate) fn begin_original_record(self: &Arc<Self>, record: &RunStartRecordV1)
    -> Result<OriginalRecordLoan, Error>
{
    let request = remote_source::expected_request(&self.source, self.fence.generation, record)?;
    self.loans.begin_record(record, remote_source::encode_record(&request, record)?)
}

pub(crate) fn run_reverse(self: &Arc<Self>, state: &Arc<crate::AgentdState>,
    cancellation: tokio_util::sync::CancellationToken)
    -> Result<(std::thread::JoinHandle<Result<(), Error>>,
        tokio::sync::oneshot::Receiver<Result<(), Error>>), Error>
{
    self.loans.attach(state, cancellation)?;
    let mut reverse = self.reverse.try_lock().map_err(|_| Error::Unavailable)?
        .take().ok_or(Error::Unavailable)?;
    let loans = Arc::clone(&self.loans);
    let (terminal, receive) = tokio::sync::oneshot::channel();
    let worker = std::thread::Builder::new().name("original-root-task-loans".into())
        .spawn(move || {
            let result: Result<(), Error> =
                (|| { while reverse.serve_one(|frame| loans.respond(frame))? {} Ok(()) })();
            let _ = terminal.send(result.clone());
            result
        }).map_err(|_| Error::Unavailable)?;
    Ok((worker, receive))
}

pub(crate) fn stop_reverse(&self) {
    // This duplicate descriptor is termination-only. It is never exposed,
    // used to send a frame, reconnected or turned into another channel.
    let _ = self.stop_reverse.shutdown(std::net::Shutdown::Both);
}

pub(crate) fn sample_original_clock(&self) -> Result<CircuitCellTimeV1, Error> {
    let (id, _) = self.loans.current_record()?;
    let bytes = self.task.try_lock().map_err(|_| Error::Unavailable)?.call(Frame {
        operation: Operation::Clock, loan: id, body: Vec::new(),
    })?;
    if bytes.len() != 16 { return Err(Error::InvalidBinding); }
    Ok(CircuitCellTimeV1 {
        circuit_millis: u64::from_be_bytes(bytes[..8].try_into().map_err(|_| Error::InvalidBinding)?),
        cell_micros: u64::from_be_bytes(bytes[8..].try_into().map_err(|_| Error::InvalidBinding)?),
    })
}

pub(super) fn original_execution(&self, admission: CircuitComputationAdmissionV2,
    input: CellStepInputV1, before: CircuitCellTimeV1) -> Result<CircuitCellExecutionV1, Error>
{
    if before.circuit_millis == u64::MAX || before.cell_micros == u64::MAX {
        return Err(Error::Unavailable);
    }
    let dispatch = admission.dispatch().clone();
    let (record_id, _) = self.loans.current_record()?;
    {
        let resolved = self.resolved.try_lock().map_err(|_| Error::Unavailable)?;
        let resolved = resolved.as_ref().ok_or(Error::ReconciliationRequired)?;
        if resolved.dispatch != dispatch || resolved.input != input { return Err(Error::InvalidBinding); }
    }
    let binding = self.registry.bind_input(&dispatch, &input)?;
    let digest = canonical_cell_step_request_digest_v1(&binding.cell, &input).map_err(CircuitCellErrorV1::from)?;
    if admission.owner_agent_id().as_str() != input.scope.agent_id.as_str()
        || admission.definition_digest() != self.registry.definition_digest()
        || admission.execution_request_digest().is_none_or(|value| value.as_str() != digest.to_string())
    { return Err(Error::InvalidBinding); }
    let id = self.loans.retain_admission(admission)?;
    let bytes = self.task.try_lock().map_err(|_| Error::Unavailable)?.call(Frame {
        operation: Operation::Execute, loan: id, body: record_id.to_be_bytes().to_vec(),
    })?;
    let decision = data::decision(&bytes)?;
    crate::circuit_cell::finish(binding, &dispatch, &input, decision).map_err(Error::from)
}

pub(crate) fn original_lookup(&self, scope: &CellScopeV1, operation: &StableId, request: Digest32)
    -> Result<Option<CellDecisionReceiptV1>, CellExecutionError>
{ self.0.lookup_original(scope, operation, request).map(Some).map_err(|_| CellExecutionError::InferencePending) }

pub(crate) fn original_execute(&self, admission: CircuitComputationAdmissionV2,
    input: CellStepInputV1, before: CircuitCellTimeV1) -> Result<CircuitCellExecutionV1, CircuitCellErrorV1>
{ self.0.original_execution(admission, input, before).map_err(|_| CircuitCellErrorV1::ReconciliationRequired) }

pub(super) fn dispatch(bytes: &[u8]) -> Result<CircuitDispatchV2, Error> {
    bounded(bytes)?;
    let data: DispatchData = serde_json::from_slice(bytes).map_err(|_| Error::InvalidBinding)?;
    if data.candidate_edges.len() > 256 {
        return Err(Error::InvalidBinding);
    }
    for text in [&data.run_id, &data.program_id, &data.node_id]
        .into_iter().chain(&data.candidate_edges)
    {
        if text.is_empty() || text.len() > 128 || text.chars().any(char::is_control) {
            return Err(Error::InvalidBinding);
        }
    }
    let value = CircuitDispatchV2 {
        run_id: data.run_id, activation_id: data.activation_id,
        program_id: data.program_id, node_id: data.node_id, round: data.round,
        input_digest: data.input_digest, input_schema: data.input_schema,
        output_schema: data.output_schema, scope_digest: data.scope_digest,
        parameter_bundle_digest: data.parameter_bundle_digest,
        route_policy_digest: data.route_policy_digest, max_work: data.max_work,
        candidate_edges: data.candidate_edges, invocation_digest: data.invocation_digest,
    };
    if encode_dispatch(&value)? != bytes { return Err(Error::InvalidBinding); }
    Ok(value)
}

pub(super) fn encode_dispatch(value: &CircuitDispatchV2) -> Result<Vec<u8>, Error> {
    let bytes = serde_json::to_vec(value).map_err(|_| Error::InvalidBinding)?;
    bounded(&bytes)?;
    Ok(bytes)
}

pub(super) fn encode_decision(value: &CellDecisionReceiptV1) -> Result<Vec<u8>, Error> {
    value.representation.validate().map_err(crate::CircuitCellErrorV1::from)?;
    let canonical = crate::circuit_cell_output::encode_receipt(value)?;
    let representation = serde_json::to_vec(&(
        &value.representation.drive_q24, &value.representation.prediction_q24,
    )).map_err(|_| Error::InvalidBinding)?;
    let mut bytes = b"HCRTDEC1".to_vec();
    blob(&mut bytes, &canonical)?;
    blob(&mut bytes, &representation)?;
    Ok(bytes)
}

pub(super) fn decision(bytes: &[u8]) -> Result<CellDecisionReceiptV1, Error> {
    let mut outer = Reader::new(bytes, b"HCRTDEC1")?;
    let encoded = outer.blob()?;
    let representation = outer.blob()?;
    outer.end()?;
    let mut r = Reader::new(encoded, b"hepta.circuit.committed-cell-decision.v1\0")?;
    let operation_id = id(&mut r)?;
    let agent_id = id(&mut r)?;
    let cell_id = id(&mut r)?;
    let run_id = id(&mut r)?;
    let selected_candidate = id(&mut r)?;
    let operation_digest = digest(&mut r)?;
    let semantic_request_digest = digest(&mut r)?;
    let principal_digest = digest(&mut r)?;
    let bundle_digest = digest(&mut r)?;
    let source_frontier = digest(&mut r)?;
    let checkpoint_before = digest(&mut r)?;
    let checkpoint_after = digest(&mut r)?;
    let model_output_digest = digest(&mut r)?;
    let confidence_ppm = u32::from_be_bytes(r.take()?);
    let ood_ppm = u32::from_be_bytes(r.take()?);
    let deadline_exceeded = boolean(&mut r)?;
    let cost = CellExecutionCostV1 {
        model_latency_micros: r.u64()?, queue_age_micros: r.u64()?,
        resident_bytes: r.u64()?, transient_allocation_bytes: r.u64()?,
        checkpoint_bytes: r.u64()?,
        consumed_input_bytes: usize::try_from(r.u64()?).map_err(|_| Error::InvalidBinding)?,
        truncated_input_bytes: usize::try_from(r.u64()?).map_err(|_| Error::InvalidBinding)?,
    };
    let count = u32::from_be_bytes(r.take()?);
    if !(1..=256).contains(&count) { return Err(Error::InvalidBinding); }
    let mut policy = Vec::new();
    for _ in 0..count {
        policy.push(CellPolicyEntryV1 {
            candidate_id: id(&mut r)?, allowed: boolean(&mut r)?,
            probability_ppm: u32::from_be_bytes(r.take()?),
        });
    }
    if r.take::<1>()? != [0] { return Err(Error::InvalidBinding); }
    r.end()?;
    let (drive_q24, prediction_q24): (Vec<i64>, Vec<i64>) =
        serde_json::from_slice(representation).map_err(|_| Error::InvalidBinding)?;
    let value = CellDecisionReceiptV1 {
        operation_id, operation_digest, semantic_request_digest,
        scope: CellScopeV1 { agent_id, cell_id, run_id, principal_digest },
        bundle_digest, source_frontier, checkpoint_before, checkpoint_after,
        model_output_digest, representation: Arc::new(CellRepresentationV1 {
            drive_q24, prediction_q24,
        }), policy, selected_candidate, confidence_ppm, ood_ppm,
        deadline_exceeded, cost, authority: AuthorityPosture::DENY_ALL,
    };
    if encode_decision(&value)? != bytes { return Err(Error::InvalidBinding); }
    Ok(value)
}

pub(super) fn new(pending: Arc<AtomicUsize>) -> Arc<Self> {
    Arc::new(Self {
        state: OnceLock::new(), cancellation: OnceLock::new(), pending,
        inner: Mutex::new(LoanState { next: 1, record: None, admission: None, completion: None }),
    })
}

pub(super) fn attach(&self, state: &Arc<AgentdState>,
    cancellation: tokio_util::sync::CancellationToken) -> Result<(), Error>
{
    self.cancellation.set(cancellation).map_err(|_| Error::InvalidBinding)?;
    self.state.set(Arc::downgrade(state)).map_err(|_| Error::InvalidBinding)
}

pub(super) fn begin_record(
    self: &Arc<Self>, record: &RunStartRecordV1, encoded: Vec<u8>,
) -> Result<OriginalRecordLoan, Error> {
    self.current_state()?.require_current_run_start(record).map_err(|_| Error::Unavailable)?;
    let mut state = self.inner.try_lock().map_err(|_| Error::Unavailable)?;
    if state.record.as_ref().is_some_and(|old| old.caller_present || old.record != *record)
        || state.admission.as_ref().is_some_and(|old| old.pending.is_some())
    { return Err(Error::Unavailable); }
    let id = allocate(&mut state)?;
    state.record = Some(RecordLoan { id, record: record.clone(), encoded, caller_present: true });
    state.admission = None;
    state.completion = None;
    Ok(OriginalRecordLoan { shared: Arc::clone(self), id })
}

pub(super) fn record(&self, original: &RunStartRecordV1) -> Result<(u64, Vec<u8>), Error> {
    let state = self.inner.try_lock().map_err(|_| Error::Unavailable)?;
    let record = state.record.as_ref().ok_or(Error::Unavailable)?;
    if !record.caller_present || record.record != *original { return Err(Error::Unavailable); }
    Ok((record.id, record.encoded.clone()))
}

pub(super) fn current_record(&self) -> Result<(u64, Vec<u8>), Error> {
    let state = self.inner.try_lock().map_err(|_| Error::Unavailable)?;
    let record = state.record.as_ref().ok_or(Error::Unavailable)?;
    if !record.caller_present { return Err(Error::Unavailable); }
    Ok((record.id, record.encoded.clone()))
}

pub(super) fn retain_admission(&self, original: CircuitComputationAdmissionV2) -> Result<u64, Error> {
    let mut state = self.inner.try_lock().map_err(|_| Error::Unavailable)?;
    let record = state.record.as_ref().ok_or(Error::Unavailable)?;
    if !record.caller_present
        || record.record.snapshot.run_id.as_str() != original.dispatch().run_id
        || state.admission.as_ref().is_some_and(|old| old.pending.is_some())
    { return Err(Error::Unavailable); }
    let record_id = record.id;
    let id = allocate(&mut state)?;
    self.pending.fetch_add(1, Ordering::AcqRel);
    state.admission = Some(AdmissionLoan { record_id, id, original, opened: false,
        pending: Some(RemoteWork(Arc::clone(&self.pending))) });
    Ok(id)
}

pub(super) fn retain_completion(
    &self, request: crate::CircuitTaskRequestV1,
    definition: codex_hepta_automation::BoundedCircuitDefinitionV2,
    saved_input: Vec<u8>, original: &CircuitTaskReceiptV1,
) -> Result<u64, Error> {
    // Validate the real receipt before making any completion loan visible.
    remote_source::original_completion_bytes(&definition, &request, &saved_input, original)?;
    let mut state = self.inner.try_lock().map_err(|_| Error::Unavailable)?;
    let record = state.record.as_ref().ok_or(Error::Unavailable)?;
    if !record.caller_present || record.record.snapshot.run_id.as_str() != request.start.run_id {
        return Err(Error::Unavailable);
    }
    let record_id = record.id;
    let id = allocate(&mut state)?;
    state.completion = Some(CompletionLoan { record_id, id, original: original.clone(),
        request, definition, saved_input });
    Ok(id)
}

pub(super) fn respond(&self, frame: Frame) -> Result<Vec<u8>, Error> {
    if frame.operation == Operation::Terminal { return self.terminal(frame); }
    let (record_id, original, encoded) = {
        let state = self.inner.try_lock().map_err(|_| Error::Unavailable)?;
        let record = state.record.as_ref().ok_or(Error::Unavailable)?;
        if !record.caller_present { return Err(Error::Unavailable); }
        (record.id, record.record.clone(), record.encoded.clone())
    };
    // No loan mutex is held across Fleet/AuthBus/readiness file I/O.
    let now = self.current_state()?.require_current_run_start(&original)
        .map_err(|_| Error::Unavailable)?;
    let mut state = self.inner.try_lock().map_err(|_| Error::Unavailable)?;
    let record = state.record.as_ref().ok_or(Error::Unavailable)?;
    if record.id != record_id || !record.caller_present || record.record != original {
        return Err(Error::Unavailable);
    }
    let mut bytes = b"HCRTCHK1".to_vec();
    bytes.extend_from_slice(&record_id.to_be_bytes());
    bytes.extend_from_slice(&now.to_be_bytes());
    blob(&mut bytes, &encoded)?;
    match frame.operation {
        Operation::CheckRecord if frame.loan == record_id && frame.body == encoded => {}
        Operation::OpenAdmission | Operation::CheckAdmission => {
            let admission = state.admission.as_mut().ok_or(Error::Unavailable)?;
            if admission.record_id != record_id || admission.id != frame.loan
                || admission.pending.is_none() || !frame.body.is_empty()
            { return Err(Error::Unavailable); }
            match frame.operation {
                Operation::OpenAdmission if !admission.opened => admission.opened = true,
                Operation::CheckAdmission if admission.opened => {}
                _ => return Err(Error::Unavailable),
            }
            blob(&mut bytes, &AdmissionData::from_original(&admission.original).encode()?)?;
        }
        Operation::ReadCompletion => {
            let completion = state.completion.as_ref().ok_or(Error::Unavailable)?;
            if completion.record_id != record_id || completion.id != frame.loan
                || !frame.body.is_empty()
            { return Err(Error::Unavailable); }
            let payload = remote_source::original_completion_bytes(&completion.definition,
                &completion.request, &completion.saved_input, &completion.original)?;
            blob(&mut bytes, &completion.saved_input)?;
            blob(&mut bytes, &payload)?;
        }
        _ => return Err(Error::InvalidBinding),
    }
    drop(state);
    self.current_state()?.require_current_run_start(&original).map_err(|_| Error::Unavailable)?;
    let state = self.inner.try_lock().map_err(|_| Error::Unavailable)?;
    if state.record.as_ref().is_none_or(|record| record.id != record_id || !record.caller_present) {
        return Err(Error::Unavailable);
    }
    Ok(bytes)
}

pub(crate) fn channel(identity: &AgentdIdentity, inputs: OriginalRootCircuitTaskDaemonInputsV1)
    -> Result<(CircuitTaskRuntimeBootstrapV1, Arc<DaemonClient>), AgentdError>
{
    let end = std::time::Instant::now() + inputs.lifetime;
    channel_until(identity, inputs, end)
}

pub(crate) fn channel_until(identity: &AgentdIdentity, inputs: OriginalRootCircuitTaskDaemonInputsV1,
    end: std::time::Instant) -> Result<(CircuitTaskRuntimeBootstrapV1, Arc<DaemonClient>), AgentdError>
{
    TaskFlowFence::new(inputs.fence.owner_agent_id.clone(), &inputs.fence.owner_id,
        inputs.fence.owner_epoch, inputs.fence.generation, &inputs.fence.fencing_token)
        .map_err(|error| AgentdError::Invalid(error.to_string()))?;
    let pending = Arc::new(AtomicUsize::new(0));
    let fence = inputs.fence.clone();
    let (client, capacity) = DaemonClient::new_until(identity, inputs, Arc::clone(&pending), end).map_err(agent_error)?;
    let (sender, mut receiver) = mpsc::channel::<Command>(capacity);
    let handle = CircuitTaskHandleV1 { sender, generation: fence.generation, pending,
        original_remote: Some(Arc::clone(&client)) };
    let original = Arc::clone(&client);
    let bootstrap = CircuitTaskRuntimeBootstrapV1 {
        identity: identity.clone(), handle, original_root: None,
        owner: Box::new(move |store, state, cancellation| Box::pin(async move {
            let (reverse, mut reverse_terminal) = original.run_reverse(&state, cancellation.clone())
                .map_err(agent_error)?;
            let result = async {
                let mut driver = CircuitTaskDriverV1 {
                    store, fence, cells: DaemonCellPort::new(Arc::clone(&original)),
                    inputs: Arc::clone(&original),
                };
                loop {
                    let command = tokio::select! {
                        _ = cancellation.cancelled() => return Ok(()),
                        stopped = &mut reverse_terminal => {
                            let detail = match stopped { Ok(Ok(())) => "Root loan stream closed".to_owned(),
                                Ok(Err(error)) => error.to_string(), Err(error) => error.to_string() };
                            return Err(AgentdError::Protocol(format!("original Root loan ended: {detail}")));
                        }
                        command = receiver.recv() => command,
                    };
                    let Some(command) = command else {
                        cancellation.cancelled().await;
                        return Ok(());
                    };
                    if command.response.is_closed() { continue; }
                    let Command { request, record, mode, response, _pending } = command;
                    let result = match request.validate_record(&record, driver.fence.generation) {
                        Err(error) => Err(error),
                        Ok(()) => driver.execute(&request, mode, || {
                            if cancellation.is_cancelled() { return Err(Error::Unavailable); }
                            let now_ms = state.require_current_run_start(&record).map_err(|_| Error::Unavailable)?;
                            let sampled = original.sample_original_clock()?;
                            Ok(CircuitCellTimeV1 { circuit_millis: sampled.circuit_millis.max(now_ms),
                                cell_micros: sampled.cell_micros })
                        }).await,
                    };
                    let _ = response.send(result);
                    drop(_pending);
                }
            }.await;
            original.stop_reverse();
            let joined = reverse.join().map_err(|_| AgentdError::Protocol("original Root loan worker panicked".into()))?;
            if !cancellation.is_cancelled() { joined.map_err(agent_error)?; }
            result
        })),
    };
    Ok((bootstrap, client))
}

pub(crate) fn new(task: HostAuthorityPeerChannel, reverse: HostAuthorityPeerChannel,
    nonce: [u8; 16], end: Instant) -> Self
{ Self { task, reverse, nonce, end } }

pub(crate) fn serve<SW, CW>(
    root: &PreparedRootHostCircuitTaskV1<SW, CW>,
    identity: &AgentdIdentity,
    mut original: OriginalRootTaskLane<SW>,
    streams: OriginalRootTaskStreams,
) -> Result<u64, Error>
where
    SW: AnchorWitnessStore + Send + 'static,
    CW: AnchorWitnessStore + Send + 'static,
{
    root.require_original_root_task_source(&original.readback).map_err(|_| Error::Unavailable)?;
    require_root_current(root)?;
    let binding = original.source.original_remote_binding()?;
    let budget = Budget::new(streams.end)?;
    let mut task = Lane::new(streams.task, binding, streams.nonce, LanePurpose::Task, Arc::clone(&budget))?;
    let reverse = ReverseClient::new(Lane::new(streams.reverse, binding, streams.nonce, LanePurpose::Loan, budget)?, binding);
    let mut retained: Option<OriginalRecord> = None;
    let mut count = 0_u64;
    while task.serve_one(|frame| {
        require_root_current(root)?;
        original.source.require_original_remote_binding(binding)?;
        let response = handle(identity, &mut original, &reverse, &mut retained, frame)?;
        original.source.require_original_remote_binding(binding)?;
        require_root_current(root)?;
        Ok(response)
    })? {
        count = count.checked_add(1).ok_or(Error::Unavailable)?;
    }
    require_root_current(root)?;
    Ok(count)
}

pub(super) fn new(end: Instant) -> Result<Arc<Self>, Error> {
    if Instant::now() >= end {
        return Err(Error::DeadlineExceeded);
    }
    Ok(Arc::new(Self { used: AtomicU64::new(0), end }))
}

pub(super) fn before(&self, deadline: Instant) -> Result<(), Error> {
    if Instant::now() >= deadline.min(self.end) {
        return Err(Error::DeadlineExceeded);
    }
    Ok(())
}

pub(super) fn new(
    channel: HostAuthorityPeerChannel,
    binding: Digest32,
    session: [u8; 16],
    purpose: LanePurpose,
    budget: Arc<Budget>,
) -> Result<Self, Error> {
    if binding.is_zero() || session == [0; 16] {
        return Err(Error::InvalidBinding);
    }
    channel.check_peer_lifetime().map_err(|_| Error::Unavailable)?;
    Ok(Self { channel: Some(channel), binding, session, sequence: 1,
        purpose, budget })
}

pub(super) fn call(&mut self, frame: Frame) -> Result<Vec<u8>, Error> {
    let mut channel = self.channel.take().ok_or(Error::Unavailable)?;
    let deadline = self.budget.begin()?;
    let request = self.encode(&frame)?;
    self.budget.before(deadline)?;
    let response = channel.request(&request).map_err(|_| Error::CommitUncertain)?;
    self.budget.before(deadline)?;
    let received = self.decode(&response)?;
    if received.operation != frame.operation || received.loan != frame.loan {
        return Err(Error::InvalidBinding);
    }
    channel.check_peer_lifetime().map_err(|_| Error::Unavailable)?;
    self.budget.before(deadline)?;
    self.sequence = self.sequence.checked_add(1).ok_or(Error::Unavailable)?;
    self.channel = Some(channel);
    Ok(received.body)
}

pub(super) fn serve_one(
    &mut self,
    handle: impl FnOnce(Frame) -> Result<Vec<u8>, Error>,
) -> Result<bool, Error> {
    let mut channel = self.channel.take().ok_or(Error::Unavailable)?;
    let mut observed_deadline = None;
    let result = channel.exchange(|bytes| {
        let deadline = self.budget.begin().map_err(transport_error)?;
        observed_deadline = Some(deadline);
        let frame = self.decode(bytes).map_err(transport_error)?;
        let operation = frame.operation;
        let loan = frame.loan;
        self.budget.before(deadline).map_err(transport_error)?;
        let body = handle(frame).map_err(transport_error)?;
        self.budget.before(deadline).map_err(transport_error)?;
        let encoded = self.encode(&Frame { operation, loan, body })
            .map_err(transport_error)?;
        self.budget.before(deadline).map_err(transport_error)?;
        Ok(encoded)
    }).map_err(|_| Error::CommitUncertain)?;
    if result {
        // The original write can itself consume the remaining time. A
        // delivered late response is Unknown and never restores this lane.
        self.budget.before(observed_deadline.ok_or(Error::Unavailable)?)?;
        channel.check_peer_lifetime().map_err(|_| Error::Unavailable)?;
        self.budget.before(observed_deadline.ok_or(Error::Unavailable)?)?;
        self.sequence = self.sequence.checked_add(1).ok_or(Error::Unavailable)?;
        self.channel = Some(channel);
    }
    Ok(result)
}

pub(super) fn bounded(bytes: &[u8]) -> Result<(), Error> {
    if bytes.is_empty() || bytes.len() > FRAME_LIMIT {
        return Err(Error::InvalidBinding);
    }
    Ok(())
}

pub(super) fn blob(bytes: &mut Vec<u8>, value: &[u8]) -> Result<(), Error> {
    let length = u32::try_from(value.len()).map_err(|_| Error::InvalidBinding)?;
    bytes.extend_from_slice(&length.to_be_bytes());
    bytes.extend_from_slice(value);
    bounded(bytes)
}

pub(super) fn new(bytes: &'a [u8], domain: &[u8]) -> Result<Self, Error> {
    bounded(bytes)?;
    Ok(Self(bytes.strip_prefix(domain).ok_or(Error::InvalidBinding)?))
}

pub(super) fn take<const N: usize>(&mut self) -> Result<[u8; N], Error> {
    let (value, rest) = self.0.split_at_checked(N).ok_or(Error::InvalidBinding)?;
    self.0 = rest;
    value.try_into().map_err(|_| Error::InvalidBinding)
}

pub(super) fn u64(&mut self) -> Result<u64, Error> {
    Ok(u64::from_be_bytes(self.take()?))
}

pub(super) fn blob(&mut self) -> Result<&'a [u8], Error> {
    let size = u32::from_be_bytes(self.take()?) as usize;
    let (value, rest) = self.0.split_at_checked(size).ok_or(Error::InvalidBinding)?;
    self.0 = rest;
    Ok(value)
}

pub(super) fn end(self) -> Result<(), Error> {
    if !self.0.is_empty() { return Err(Error::InvalidBinding); }
    Ok(())
}

pub(crate) fn encode(out: &mut Writer, cell: &CellDefinitionV1) -> Result<(), Error> {
    cell.semantic_digest().map_err(|_| Error::InvalidBinding)?;
    out.id(&cell.cell_id)?;
    out.digest(cell.bundle_digest)?;
    out.digest(cell.state_schema_digest)?;
    runtime(out, &cell.runtime)?;
    native(out, &cell.native)?;
    out.count(cell.candidates.len(), 256)?;
    for candidate in &cell.candidates {
        out.id(&candidate.candidate_id)?;
        out.size(candidate.activation_index)?;
        out.byte(match candidate.kind { CellCandidateKindV1::Action => 1,
            CellCandidateKindV1::Abstain => 2, CellCandidateKindV1::SlowPath => 3 })?;
    }
    out.size(cell.max_input_bytes)?;
    out.u64(cell.max_queue_age_micros)?;
    out.u64(cell.max_resident_bytes)
}

pub(crate) fn decode(input: &mut Reader<'_>) -> Result<CellDefinitionV1, Error> {
    let cell_id = input.id()?;
    let bundle_digest = input.digest()?;
    let state_schema_digest = input.digest()?;
    let runtime = read_runtime(input)?;
    let native = read_native(input)?;
    let mut candidates = Vec::new();
    for _ in 0..input.count(256)? {
        candidates.push(CellCandidateV1 { candidate_id: input.id()?, activation_index: input.size()?,
            kind: match input.byte()? { 1 => CellCandidateKindV1::Action, 2 => CellCandidateKindV1::Abstain,
                3 => CellCandidateKindV1::SlowPath, _ => return Err(Error::InvalidBinding) } });
    }
    let cell = CellDefinitionV1 { cell_id, bundle_digest, state_schema_digest, runtime, native, candidates,
        max_input_bytes: input.size()?, max_queue_age_micros: input.u64()?, max_resident_bytes: input.u64()? };
    cell.semantic_digest().map_err(|_| Error::InvalidBinding)?;
    Ok(cell)
}

pub(crate) fn raw(&mut self, data: &[u8]) -> Result<(), Error> {
    if self.0.len().checked_add(data.len()).is_none_or(|n| n > BOUND) {
        return Err(Error::InvalidBinding);
    }
    self.0.extend_from_slice(data);
    Ok(())
}

pub(crate) fn size(&mut self, value: usize) -> Result<(), Error> {
    self.u64(u64::try_from(value).map_err(|_| Error::InvalidBinding)?)
}

pub(crate) fn count(&mut self, value: usize, bound: usize) -> Result<(), Error> {
    if value > bound { return Err(Error::InvalidBinding); }
    self.u32(u32::try_from(value).map_err(|_| Error::InvalidBinding)?)
}

pub(crate) fn bytes(&mut self, value: &[u8]) -> Result<(), Error> {
    self.u32(u32::try_from(value.len()).map_err(|_| Error::InvalidBinding)?)?;
    self.raw(value)
}

pub(crate) fn text(&mut self, value: &str) -> Result<(), Error> {
    if value.is_empty() || value.len() > 128 || value.chars().any(char::is_control) {
        return Err(Error::InvalidBinding);
    }
    self.bytes(value.as_bytes())
}

pub(crate) fn json<T: Serialize>(&mut self, value: &T) -> Result<(), Error> {
    self.bytes(&serde_json::to_vec(value).map_err(|_| Error::InvalidBinding)?)
}

pub(crate) fn new(data: &'a [u8], domain: &[u8]) -> Result<Self, Error> {
    if data.len() > BOUND { return Err(Error::InvalidBinding); }
    Ok(Self(data.strip_prefix(domain).ok_or(Error::InvalidBinding)?))
}

pub(crate) fn take<const N: usize>(&mut self) -> Result<[u8; N], Error> {
    let (value, rest) = self.0.split_at_checked(N).ok_or(Error::InvalidBinding)?;
    self.0 = rest;
    value.try_into().map_err(|_| Error::InvalidBinding)
}

pub(crate) fn size(&mut self) -> Result<usize, Error> {
    usize::try_from(self.u64()?).map_err(|_| Error::InvalidBinding)
}

pub(crate) fn count(&mut self, bound: usize) -> Result<usize, Error> {
    let n = self.u32()? as usize;
    if n > bound || n > self.0.len() { return Err(Error::InvalidBinding); }
    Ok(n)
}

pub(crate) fn bytes(&mut self) -> Result<&'a [u8], Error> {
    let n = self.u32()? as usize;
    let (value, rest) = self.0.split_at_checked(n).ok_or(Error::InvalidBinding)?;
    self.0 = rest;
    Ok(value)
}

pub(crate) fn text(&mut self) -> Result<String, Error> {
    let value = std::str::from_utf8(self.bytes()?).map_err(|_| Error::InvalidBinding)?;
    if value.is_empty() || value.len() > 128 || value.chars().any(char::is_control) {
        return Err(Error::InvalidBinding);
    }
    Ok(value.to_owned())
}

pub(crate) fn id(&mut self) -> Result<StableId, Error> {
    StableId::new(self.text()?).map_err(|_| Error::InvalidBinding)
}

pub(crate) fn generation(&mut self) -> Result<Generation, Error> {
    Generation::new(self.u64()?).map_err(|_| Error::InvalidBinding)
}

pub(crate) fn json<T: DeserializeOwned + Serialize>(&mut self) -> Result<T, Error> {
    let bytes = self.bytes()?;
    let value: T = serde_json::from_slice(bytes).map_err(|_| Error::InvalidBinding)?;
    if serde_json::to_vec(&value).map_err(|_| Error::InvalidBinding)? != bytes {
        return Err(Error::InvalidBinding);
    }
    Ok(value)
}

pub(crate) fn end(self) -> Result<(), Error> {
    if self.0.is_empty() { Ok(()) } else { Err(Error::InvalidBinding) }
}

pub(crate) fn retain_original_remote_record(&self, record: &RunStartRecordV1)
    -> Result<Option<super::remote::OriginalRecordLoan>, AgentdError>
{
    self.original_remote.as_ref().map(|client| client.begin_original_record(record))
        .transpose().map_err(|error| AgentdError::Protocol(format!("original Root RunStart loan: {error}")))
}

pub(crate) fn original_root_handoff_registry(&self) -> Result<(Vec<u8>, usize), Error> {
    self.original_root.as_ref().ok_or(Error::Unavailable)?.original_handoff_registry()
}

pub(crate) fn take_original_root_lane(&mut self)
    -> Result<Box<dyn super::root_lane::OriginalRootCellPump>, Error>
{
    self.original_root.take().ok_or(Error::Unavailable)?.take()
}

pub(crate) fn original_root_handoff_source(&self) -> Result<(Digest32, Vec<u8>), Error> {
    let mut owner = self.0.lock().map_err(|_| Error::Unavailable)?;
    owner.require_current()?;
    if owner.sources.len() != 1 { return Err(Error::InvalidBinding); }
    let source = owner.sources.values().next().ok_or(Error::InvalidBinding)?;
    let bytes = encode(&owner.fence, source)?;
    let binding = owner.binding;
    owner.require_current()?;
    Ok((binding, bytes))
}

pub(crate) fn decode(bytes: &[u8]) -> Result<(TaskFlowFence, CircuitTaskSourceInputV1), Error> {
    let mut reader = Reader::new(bytes, b"HCRTSRC1")?;
    let fence = reader.json()?;
    let input = codec::decode_configuration_input(reader.bytes()?)?;
    let source = CircuitTaskSourceInputV1 { scope: input.scope, source_frontier: input.source_frontier,
        objective_digest: input.objective_digest, ndu_snapshot_digest: input.ndu_snapshot_digest,
        monotonic_micros: input.monotonic_micros, deadline_micros: input.deadline_micros,
        observation: input.observation, candidates: input.candidates, lease_duration_ms: reader.u64()? };
    reader.end()?;
    if encode(&fence, &source)? != bytes { return Err(Error::InvalidBinding); }
    Ok((fence, source))
}

pub(super) fn encode_input(input: &CellStepInputV1) -> Result<Vec<u8>, Error> {
    if input.scope.principal_digest.is_zero()
        || input.source_frontier.is_zero()
        || input.objective_digest.is_zero()
        || input.ndu_snapshot_digest.is_zero()
        || input.monotonic_micros == 0
        || input.deadline_micros <= input.monotonic_micros
        || input.observation.is_empty()
        || input.observation.len() > 32 * 1_024
        || !(1..=64).contains(&input.candidates.len())
        || input.candidates.iter().enumerate().any(|(i, c)| {
            input.candidates[..i]
                .iter()
                .any(|p| p.candidate_id == c.candidate_id)
        })
    {
        return Err(Error::InvalidBinding);
    }
    let mut bytes = Vec::new();
    for id in [
        &input.operation_id,
        &input.scope.agent_id,
        &input.scope.cell_id,
        &input.scope.run_id,
    ] {
        blob(&mut bytes, id.as_str().as_bytes());
    }
    for digest in [
        input.scope.principal_digest,
        input.source_frontier,
        input.objective_digest,
        input.ndu_snapshot_digest,
    ] {
        bytes.extend_from_slice(digest.as_array());
    }
    bytes.extend_from_slice(&input.monotonic_micros.to_be_bytes());
    bytes.extend_from_slice(&input.deadline_micros.to_be_bytes());
    blob(&mut bytes, &input.observation);
    bytes.extend_from_slice(&(input.candidates.len() as u32).to_be_bytes());
    for mask in &input.candidates {
        blob(&mut bytes, mask.candidate_id.as_str().as_bytes());
        bytes.push(u8::from(mask.allowed));
    }
    bounded(&bytes)?;
    Ok(bytes)
}

pub(super) fn decode_configuration_input(encoded: &[u8]) -> Result<CellStepInputV1, Error> {
    let mut r = Reader(encoded);
    let input = CellStepInputV1 {
        operation_id: r.id()?,
        scope: CellScopeV1 {
            agent_id: r.id()?,
            cell_id: r.id()?,
            run_id: r.id()?,
            principal_digest: r.digest()?,
        },
        source_frontier: r.digest()?,
        objective_digest: r.digest()?,
        ndu_snapshot_digest: r.digest()?,
        monotonic_micros: u64::from_be_bytes(r.take()?),
        deadline_micros: u64::from_be_bytes(r.take()?),
        observation: r.blob()?.to_vec(),
        candidates: {
            let count = u32::from_be_bytes(r.take()?);
            if !(1..=64).contains(&count) {
                return Err(Error::InvalidBinding);
            }
            let mut masks = Vec::with_capacity(count as usize);
            for _ in 0..count {
                let candidate_id = r.id()?;
                let allowed = match r.take::<1>()? {
                    [0] => false,
                    [1] => true,
                    _ => return Err(Error::InvalidBinding),
                };
                masks.push(CellCandidateMaskV1 {
                    candidate_id,
                    allowed,
                });
            }
            masks
        },
    };
    r.end()?;
    if encode_input(&input)? != encoded {
        return Err(Error::InvalidBinding);
    }
    Ok(input)
}

pub(crate) fn from_original_material_root_stream(
    stream: UnixStream,
    root: AgentdRootAuthorityPeer,
    root_pidfd: OwnedFd,
    config: OriginalCellQ24MaterialReceiptConfigV1,
    identity: AgentdIdentity,
    nonce: [u8; 16],
    timeout: Duration,
    lifetime: Duration,
) -> Result<Self, Error> {
    if timeout.is_zero() || timeout > wire::TIMEOUT
        || lifetime.is_zero() || lifetime > Duration::from_secs(300)
        || nonce == [0; 16]
    { return Err(Error::InvalidBinding); }
    let end = Instant::now() + lifetime;
    let binding = wire::context(&config)?;
    let original = original_owner_command_channel_v1(stream, root, /*uid*/ 0,
        root_pidfd, timeout, lifetime).map_err(|_| Error::Unavailable)?;
    if wire::context(&config)? != binding { return Err(Error::InvalidBinding); }
    wire::before(end)?;
    Ok(Self { original: OriginalReadback::RootMaterial(Arc::new(Client {
        slot: Mutex::new(Some(Channel { original, next: 1 })), config, identity,
        binding, nonce, timeout, end,
    })) })
}

pub(super) fn read(&self, identity: &AgentdIdentity, run: &StableId)
    -> Result<CircuitTaskSourcePublicationV1, Error>
{
    if identity != &self.identity || run != &self.config.initial.request.source_run_id {
        return Err(Error::InvalidBinding);
    }
    let mut channel = self.slot.try_lock().map_err(|_| Error::Unavailable)?
        .take().ok_or(Error::Unavailable)?;
    let deadline = (Instant::now() + self.timeout).min(self.end);
    wire::before(deadline)?;
    if wire::context(&self.config)? != self.binding { return Err(Error::InvalidBinding); }
    let request = wire::request(self.binding, self.nonce, channel.next)?;
    channel.next = channel.next.checked_add(1).ok_or(Error::Unavailable)?;
    let response = channel.original.request(&request).map_err(|_| Error::CommitUncertain)?;
    wire::before(deadline)?;
    let payload = wire::read_response(&request, &response)?;
    // Only this successful fixed Root exchange reaches the private decoder.
    // No public/raw-result overload manufactures an original publication.
    let observed = decode_current_root_payload(payload)?;
    crate::cell_q24_dataset::require_source(identity, &observed, &self.config.initial.request)
        .map_err(|_| Error::InvalidBinding)?;
    channel.original.check_peer_lifetime().map_err(|_| Error::Unavailable)?;
    if wire::context(&self.config)? != self.binding { return Err(Error::InvalidBinding); }
    let mut slot = self.slot.try_lock().map_err(|_| Error::Unavailable)?;
    wire::before(deadline)?;
    *slot = Some(channel);
    Ok(observed)
}

pub(crate) fn encode_original_material_publication(
    &self, identity: &AgentdIdentity, expected: &CircuitTaskSourcePublicationV1,
) -> Result<Vec<u8>, Error> {
    let OriginalReadback::Local(original) = &self.original else {
        return Err(Error::InvalidBinding);
    };
    if original.read_publication(identity, expected.original_record())? != *expected {
        return Err(Error::InvalidBinding);
    }
    let mut owner = original.0.try_lock().map_err(|_| Error::Unavailable)?;
    let request = owner.request(identity, expected.original_record())?;
    let request_bytes = codec::request(&request, expected.original_record())?;
    owner.require_bytes("request", &request.start.run_id, &request_bytes)?;
    let saved = owner.read("input", &request.start.run_id)?;
    let result = owner.read("result", &request.start.run_id)?;
    if codec::decode_input(&saved)? != *expected.input() || result != expected.result_bytes() {
        return Err(Error::InvalidBinding);
    }
    let mut out = wire::Writer::new(b"HCMATPUB1");
    out.digest(owner.binding)?;
    out.bytes(&request_bytes)?;
    out.bytes(&saved)?;
    out.bytes(&result)?;
    owner.require_active(&request.start.run_id)?;
    owner.require_current()?;
    let payload = out.finish();
    wire::bounded(&payload)?;
    Ok(payload)
}

pub(crate) fn context(config: &OriginalCellQ24MaterialReceiptConfigV1) -> Result<Digest32, Error> {
    let at = SystemTime::now().duration_since(UNIX_EPOCH)
        .map_err(|_| Error::Unavailable)?.as_secs();
    OriginalCellQ24MaterialReceiptConfigV1::original_source_loan_binding(config, at)
        .map_err(|_| Error::InvalidBinding)
}

pub(crate) fn before(end: Instant) -> Result<(), Error> {
    if Instant::now() >= end { return Err(Error::DeadlineExceeded); }
    Ok(())
}

pub(crate) fn bounded(bytes: &[u8]) -> Result<(), Error> {
    if bytes.is_empty() || bytes.len() > BOUND { return Err(Error::InvalidBinding); }
    Ok(())
}

pub(crate) fn request(binding: Digest32, nonce: [u8; 16], id: u64) -> Result<Vec<u8>, Error> {
    if binding.is_zero() || nonce == [0; 16] || !(1..=LIMIT).contains(&id) {
        return Err(Error::InvalidBinding);
    }
    let mut bytes = b"HCMATRD1".to_vec();
    bytes.extend_from_slice(binding.as_array());
    bytes.extend_from_slice(&nonce);
    bytes.extend_from_slice(&id.to_be_bytes());
    Ok(bytes)
}

pub(crate) fn response(request: &[u8], payload: &[u8]) -> Result<Vec<u8>, Error> {
    let mut bytes = request.to_vec();
    bytes.extend_from_slice(payload);
    bounded(&bytes)?;
    Ok(bytes)
}

pub(crate) fn read_response<'a>(request: &[u8], response: &'a [u8]) -> Result<&'a [u8], Error> {
    bounded(response)?;
    response.strip_prefix(request).filter(|payload| !payload.is_empty())
        .ok_or(Error::InvalidBinding)
}

pub(crate) fn original_binding(
    identity: &AgentdIdentity,
    fence: &TaskFlowFence,
    registry: &CircuitCellRegistryV1,
    source: &CircuitTaskSourceInputV1,
) -> Result<Digest32, Error> {
    let (_, binding) = codec::configuration(identity, fence, registry, vec![source.clone()])?;
    Ok(binding)
}

pub(crate) fn expected_request(
    source: &CircuitTaskSourceInputV1,
    generation: u64,
    record: &RunStartRecordV1,
) -> Result<CircuitTaskRequestV1, Error> {
    if source.scope.run_id != record.snapshot.run_id { return Err(Error::InvalidBinding); }
    let created_at_ms = record.admission.observed_at_unix_micros / 1_000;
    let deadline_ms = (record.admission.deadline_unix_micros / 1_000)
        .min(record.authentication.expires_at_ms);
    let request = CircuitTaskRequestV1 {
        start: CircuitStartV2 {
            run_id: record.snapshot.run_id.to_string(),
            scope_digest: circuit_cell_scope_digest_v1(&source.scope)?,
            input_digest: Sha256Digest::for_bytes(&source.observation),
            created_at_ms, lease_duration_ms: source.lease_duration_ms,
        }, objective_digest: source.objective_digest, deadline_ms,
    };
    request.validate_record(record, generation)?;
    if source.deadline_micros.checked_sub(source.monotonic_micros)
        .is_none_or(|duration| duration > deadline_ms.saturating_sub(created_at_ms).saturating_mul(1_000))
    { return Err(Error::InvalidBinding); }
    Ok(request)
}

pub(crate) fn encode_record(
    request: &CircuitTaskRequestV1, record: &RunStartRecordV1,
) -> Result<Vec<u8>, Error> { codec::request(request, record) }

pub(crate) fn decode_record(bytes: &[u8]) -> Result<RunStartRecordV1, Error> {
    codec::original_record(bytes)
}

pub(crate) fn decode_original_input(bytes: &[u8]) -> Result<CellStepInputV1, Error> {
    codec::decode_input(bytes)
}

pub(crate) fn encode_original_input(
